mapper.select:
/* CommonCodeMapper.selectCommonCodeList 조회 조건에 맞는 공통코드 분류 목록을 업무모듈·정렬순번 순으로 조회 */ SELECT WRK_MDUL_CD, COMM_CTG_CD, COALESCE(COMM_CTG_NM, '') AS COMM_CTG_NM, COALESCE(COMM_PROP_NM_1, '') AS COMM_PROP_NM_1, COALESCE(COMM_PROP_NM_2, '') AS COMM_PROP_NM_2, COALESCE(COMM_PROP_NM_3, '') AS COMM_PROP_NM_3, COALESCE(COMM_PROP_NM_4, '') AS COMM_PROP_NM_4, COALESCE(COMM_PROP_NM_5, '') AS COMM_PROP_NM_5, COALESCE(COMM_PROP_NM_6, '') AS COMM_PROP_NM_6, COALESCE(COMM_PROP_NM_7, '') AS COMM_PROP_NM_7, COALESCE(COMM_PROP_NM_8, '') AS COMM_PROP_NM_8, COALESCE(COMM_PROP_NM_9, '') AS COMM_PROP_NM_9, COALESCE(COMM_PROP_NM_10, '') AS COMM_PROP_NM_10, USE_YN, USR_MNGE_YN, ALIN_SEQ, COALESCE(RMK, '') AS RMK FROM TB_COMM_CD_M
AND WRK_MDUL_CD = #{wrkMdulCd}
AND UPPER(COMM_CTG_CD) LIKE '%' || UPPER(TRIM(#{commCtgCd})) || '%'
AND COMM_CTG_NM LIKE '%' || TRIM(#{commCtgNm}) || '%'
ORDER BY WRK_MDUL_CD, ALIN_SEQ NULLS LAST, COMM_CTG_CD

/* CommonCodeMapper.selectCommonCodeDetailList 공통분류의 상세코드 목록을 정렬순번 순으로 조회 */ SELECT D.WRK_MDUL_CD, D.COMM_CTG_CD, D.COMM_CTG_DTL_CD, COALESCE(D.COMM_CTG_DTL_NM, '') AS COMM_CTG_DTL_NM, COALESCE(D.COMM_PROP_CONT_1, '') AS COMM_PROP_CONT_1, COALESCE(D.COMM_PROP_CONT_2, '') AS COMM_PROP_CONT_2, COALESCE(D.COMM_PROP_CONT_3, '') AS COMM_PROP_CONT_3, COALESCE(D.COMM_PROP_CONT_4, '') AS COMM_PROP_CONT_4, COALESCE(D.COMM_PROP_CONT_5, '') AS COMM_PROP_CONT_5, COALESCE(D.COMM_PROP_CONT_6, '') AS COMM_PROP_CONT_6, COALESCE(D.COMM_PROP_CONT_7, '') AS COMM_PROP_CONT_7, COALESCE(D.COMM_PROP_CONT_8, '') AS COMM_PROP_CONT_8, COALESCE(D.COMM_PROP_CONT_9, '') AS COMM_PROP_CONT_9, COALESCE(D.COMM_PROP_CONT_10, '') AS COMM_PROP_CONT_10, COALESCE(D.RMK, '') AS RMK, D.USE_YN, D.ALIN_SEQ FROM TB_COMM_CD_D D JOIN TB_COMM_CD_M M ON M.WRK_MDUL_CD = D.WRK_MDUL_CD AND M.COMM_CTG_CD = D.COMM_CTG_CD WHERE D.WRK_MDUL_CD = #{wrkMdulCd} AND D.COMM_CTG_CD = #{commCtgCd}
AND M.USE_YN = #{useYn} AND D.USE_YN = #{useYn}
ORDER BY D.ALIN_SEQ NULLS LAST, D.COMM_CTG_DTL_CD

mapper.delete:
/* CommonCodeMapper.deleteCommonCode 공통코드 분류를 삭제 */
DELETE FROM TB_COMM_CD_M
 WHERE WRK_MDUL_CD = #{wrkMdulCd}
   AND COMM_CTG_CD = #{commCtgCd}

mapper.select:
/* CommonCodeMapper.existsCommonCodeDetail 공통코드 상세가 등록되어 있는지 판별 (상세코드가 없으면 분류에 코드가 1건이라도 있는지) */
SELECT EXISTS (
    SELECT 1
      FROM TB_COMM_CD_D
     WHERE WRK_MDUL_CD = #{wrkMdulCd}
       AND COMM_CTG_CD = #{commCtgCd}

       AND COMM_CTG_DTL_CD = #{commCtgDtlCd}

)
